using System;using System.Globalization;using System.IO;using System.Windows.Data;using System.Windows.Media.Imaging;
namespace PhotoBooth.Customer.UI.Converters { public sealed class ByteArrayImageConverter:IValueConverter { public object Convert(object v,Type t,object p,CultureInfo c){var bytes=v as byte[];if(bytes==null||bytes.Length==0)return null;var b=new BitmapImage();using(var s=new MemoryStream(bytes)){b.BeginInit();b.CacheOption=BitmapCacheOption.OnLoad;b.StreamSource=s;b.EndInit();b.Freeze();}return b;}public object ConvertBack(object v,Type t,object p,CultureInfo c)=>Binding.DoNothing;} }
